// MINI with a broken screen: Bluetooth pairing with the phone through the PC.
// Firmware ≥ 0.6.17 announces each pairing passkey on USB; the Companion types
// it into the phone over adb. No Wi-Fi is involved: MINI talks to MEL through
// the phone over Bluetooth.

export const MINI_BLE_PASSKEY_FIRMWARE = '0.6.17-usb-ble-passkey';

// Bluetooth pairing MINI ↔ phone without the MINI's screen (firmware ≥ 0.6.17):
// the MINI announces each pairing passkey on USB ("MELBLE PASSKEY nnnnnn");
// the Companion turns the phone's Bluetooth on, waits for the passkey and types
// it into Android's pairing dialog through adb (already paired with this PC).
const BLE_PAIR = String.raw`
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$adb=@((Join-Path $env:LOCALAPPDATA 'Android\platform-tools\adb.exe'),(Join-Path $env:LOCALAPPDATA 'MEL\tools\platform-tools\adb.exe'),@(Get-Command adb.exe -All -ErrorAction SilentlyContinue|ForEach-Object{$_.Source}))|Where-Object{$_ -and (Test-Path -LiteralPath $_)}|Select-Object -First 1
if(-not $adb){throw 'ADB_NOT_INSTALLED_USE_CONFIGURER_ADB_WIFI'}
function A([string[]]$a){$p=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$o=@(& $adb @a 2>&1|ForEach-Object{[string]$_})}finally{$ErrorActionPreference=$p};return ($o -join [string][char]10)}
$devs=@([regex]::Matches((A @('devices')),'(?m)^(\S+)\s+device\s*$')|ForEach-Object{$_.Groups[1].Value})
if($devs.Count -lt 1){throw 'ANDROID_DEVICE_NOT_FOUND'}
# The same phone can appear twice (IP:port and mDNS name): one is enough.
$devs=@($devs|Sort-Object {$_ -notmatch '^\d'})
$s=$devs[0]
$ports=@(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue|ForEach-Object{if(([string]$_.PNPDeviceID) -match '^USB\\VID_303A&PID_1001' -and ([string]$_.Name) -match '\((COM\d{1,3})\)'){$Matches[1]}}|Sort-Object -Unique)
if($ports.Count -ne 1){throw ('MINI_USB_PORT_NOT_UNIQUE:'+$ports.Count)}
$sp=New-Object IO.Ports.SerialPort $ports[0],115200
$sp.DtrEnable=$false;$sp.RtsEnable=$false;$sp.ReadTimeout=300
$sp.Open()
$typed=@();$log=@()
try{
 [void](A @('-s',$s,'shell','cmd','bluetooth_manager','enable'))
 $buf='';$deadline=(Get-Date).AddSeconds(100)
 while((Get-Date) -lt $deadline){
  try{$buf+=$sp.ReadExisting()}catch{}
  $m=[regex]::Match($buf,'MELBLE PASSKEY (\d{6})')
  if($m.Success){
   $pk=$m.Groups[1].Value;$buf=$buf.Substring($m.Index+$m.Length)
   if($typed -notcontains $pk){
    Start-Sleep -Seconds 2
    [void](A @('-s',$s,'shell','input','text',$pk))
    Start-Sleep -Milliseconds 700
    [void](A @('-s',$s,'shell','uiautomator','dump','/sdcard/mel-ui.xml'))
    $ui=A @('-s',$s,'shell','cat','/sdcard/mel-ui.xml')
    $b=[regex]::Match($ui,'text="(?:Associer|ASSOCIER|Appairer|Pair|PAIR|OK)"[^>]*bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"')
    if($b.Success){$x=[int](([int]$b.Groups[1].Value+[int]$b.Groups[3].Value)/2);$y=[int](([int]$b.Groups[2].Value+[int]$b.Groups[4].Value)/2);[void](A @('-s',$s,'shell','input','tap',"$x","$y"));$log+='tap '+$x+','+$y}else{[void](A @('-s',$s,'shell','input','keyevent','66'));$log+='enter'}
    $typed+=$pk
    $deadline=(Get-Date).AddSeconds(25)
   }
  }
  Start-Sleep -Milliseconds 300
 }
}finally{try{$sp.Close()}catch{}}
$bonded=A @('-s',$s,'shell','dumpsys','bluetooth_manager')
$mel=@([regex]::Matches($bonded,'(?im)^\s*(?:name|Name)?[:\s]*(MEL[^\r\n]{0,40})')|ForEach-Object{$_.Groups[1].Value.Trim()}|Select-Object -Unique -First 5)
[ordered]@{action='mini.ble.pair';phone=$s;port=$ports[0];passkeys_typed=$typed.Count;steps=$log;mel_devices_seen=$mel}|ConvertTo-Json -Compress
if($typed.Count -eq 0){exit 3}
`;

export function miniBlePairCommand() {
  return { command: BLE_PAIR, timeout_ms: 120000 };
}

// MEL-FOUNDER-06: software bench for the Companion/Android/MINI protocol.
// It runs pairing, shutdown, permissions and disconnection against an
// EXPLICIT double, so CI proves the protocol without any hardware. What it
// proves is the protocol, never the device: the physical recipe below stays
// separate and unvalidated until a real device runs it.
export const MINI_PROTOCOL_STEPS = Object.freeze(['pair', 'permissions', 'shutdown', 'disconnect']);

export const MINI_PHYSICAL_RECIPE = Object.freeze({
  schema: 'mel.mini-physical-recipe/v1',
  validated: false,
  reason: 'PHYSICAL_DEVICE_PROOF_REQUIRED',
  steps: Object.freeze(['brancher le MINI en USB', 'lancer l’appairage BLE depuis le téléphone',
    'accorder les autorisations Android', 'couper l’alimentation', 'vérifier la déconnexion propre']),
});

// The double must say what it is. A silent fake that looks like a device is
// how a bench ends up claiming a hardware proof it never had.
export function createMiniProtocolDouble({ fails = [] } = {}) {
  const failing = new Set(fails);
  const calls = [];
  return {
    kind: 'EXPLICIT_DOUBLE',
    hardware: false,
    calls,
    async run(step) {
      calls.push(step);
      if (failing.has(step)) return { ok: false, code: 'MINI_' + step.toUpperCase() + '_FAILED' };
      return { ok: true, step };
    },
  };
}

export async function runMiniProtocolBench(double) {
  if (!double || double.kind !== 'EXPLICIT_DOUBLE' || double.hardware !== false) {
    throw Object.assign(new Error('MINI_BENCH_EXPLICIT_DOUBLE_REQUIRED'), { code: 'MINI_BENCH_EXPLICIT_DOUBLE_REQUIRED' });
  }
  const steps = [];
  for (const step of MINI_PROTOCOL_STEPS) {
    const result = await double.run(step).catch(error => ({ ok: false, code: String(error?.code || 'MINI_STEP_THREW') }));
    steps.push({ step, ok: result?.ok === true, code: result?.ok === true ? null : String(result?.code || 'MINI_STEP_FAILED') });
  }
  return {
    schema: 'mel.mini-protocol-bench/v1',
    steps,
    passed: steps.every(row => row.ok),
    // Never conflated with a device acceptance.
    proves: 'PROTOCOL_ONLY',
    hardware_validated: false,
    physical_recipe: MINI_PHYSICAL_RECIPE,
  };
}

import { CiProviderAdapter } from './ci-provider-adapter.js';

function req(fn,code){if(typeof fn!=='function')throw Object.assign(new TypeError(code),{code});return fn;}
function clean(v,max=240){return String(v||'').trim().slice(0,max);}

export function createCompanionCiProviderAdapter({
  execute,
  id='companion-local-ci',
  provider='local-companion-ci',
  repository='meliturgos-cloudflare',
}={}){
  const rpc=req(execute,'COMPANION_CI_EXECUTOR_REQUIRED');
  const repo=clean(repository,200);
  if(!repo)throw Object.assign(new TypeError('COMPANION_CI_REPOSITORY_REQUIRED'),{code:'COMPANION_CI_REPOSITORY_REQUIRED'});

  const call=async(action,payload={})=>{
    const result=await rpc({
      capability:'sovereignty.ci',
      action,
      repository:repo,
      payload,
    });
    if(result?.ok!==true){
      throw Object.assign(new Error(result?.code||'COMPANION_CI_FAILED'),{code:result?.code||'COMPANION_CI_FAILED'});
    }
    return result;
  };

  return new CiProviderAdapter({
    id,
    provider,
    health:async()=>{
      try{
        const result=await call('health');
        return{ok:true,status:'HEALTHY',node_version:clean(result?.node_version,120)||null};
      }catch(error){
        return{ok:false,status:'UNAVAILABLE',code:error.code||error.message};
      }
    },
    dispatch:async({pipeline,source_sha,mode})=>{
      const result=await call('dispatch',{
        pipeline:clean(pipeline,200),
        source_sha:clean(source_sha,80),
        mode:clean(mode,80),
      });
      return{ok:true,run_id:clean(result?.run_id,200)};
    },
    getRun:async({run_id})=>{
      const result=await call('get_run',{run_id:clean(run_id,200)});
      return{
        ok:true,
        run_id:clean(result?.run_id,200),
        source_sha:clean(result?.source_sha,80),
        status:clean(result?.status,80),
      };
    },
    cancelRun:async({run_id})=>{
      await call('cancel_run',{run_id:clean(run_id,200)});
      return{ok:true};
    },
    getArtifacts:async({run_id})=>{
      const result=await call('get_artifacts',{run_id:clean(run_id,200)});
      return{ok:true,artifacts:Array.isArray(result?.artifacts)?result.artifacts:[]};
    },
  });
}

// MEL-FOUNDER-06: an explicit double of the Companion executor, so the CI
// adapter is exercised without a Windows companion. It announces itself as a
// double; nothing may read its answers as a real companion run.
export function createCompanionExecutorDouble({ healthy = true, dispatch = true, nodeVersion = 'v20.0.0' } = {}) {
  const calls = [];
  const double = async ({ action, repository, payload } = {}) => {
    calls.push({ action, repository, payload });
    if (action === 'health') {
      return healthy ? { ok: true, node_version: nodeVersion } : { ok: false, code: 'COMPANION_UNAVAILABLE' };
    }
    if (!dispatch) return { ok: false, code: 'COMPANION_DISPATCH_REFUSED' };
    return { ok: true, run_id: 'double-' + calls.length };
  };
  double.kind = 'EXPLICIT_DOUBLE';
  double.hardware = false;
  double.calls = calls;
  return double;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { onRequestGet } from '../src/pages/full-interface-v2.js';

test('full interface exposes the Waveshare terminal setup surface',async()=>{
  const r=await onRequestGet();
  const html=await r.text();
  assert.match(html,/data-view="terminal"/);
  assert.match(html,/data-panel="terminal"/);
  assert.match(html,/Créer un code d’appairage/);
  assert.match(html,/\/api\/device\/v1\/pair-code/);
  // The manual flashing script is superseded by the one-click Companion update.
  assert.match(html,/id="miniFlashCompanion"/);
  assert.doesNotMatch(html,/href="\/api\/device\/v1\/setup-script"/);
});

// MEL-FOUNDER-06: the bench proves the protocol, never the device. The MINI
// surface must not present a software run as a validated physical device.
test('the MINI surface never presents the software bench as a validated device', async () => {
  const { MINI_PHYSICAL_RECIPE, runMiniProtocolBench, createMiniProtocolDouble } = await import('../src/devices/mini-usb-provision.js');
  assert.equal(MINI_PHYSICAL_RECIPE.validated, false);
  assert.ok(MINI_PHYSICAL_RECIPE.steps.length >= 4, 'the physical recipe stays written down, separate from the bench');
  const bench = await runMiniProtocolBench(createMiniProtocolDouble());
  assert.equal(bench.hardware_validated, false);
  assert.equal(bench.proves, 'PROTOCOL_ONLY');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createCompanionCiProviderAdapter } from '../../src/portability/companion-ci-provider-adapter.js';
import { CiProviderAdapter, proveCiProviderAdapter } from '../../src/portability/ci-provider-adapter.js';

function executor(){
  return async({action,payload})=>{
    if(action==='health')return{ok:true,node_version:'22.20.0'};
    if(action==='dispatch')return{ok:true,run_id:'local-run-1'};
    if(action==='get_run')return{ok:true,run_id:payload.run_id,source_sha:'a'.repeat(40),status:'SUCCEEDED'};
    if(action==='get_artifacts')return{ok:true,artifacts:[{id:'proof',path:'proof.json'}]};
    if(action==='cancel_run')return{ok:true};
    return{ok:false,code:'UNKNOWN_ACTION'};
  };
}

test('companion CI adapter satisfies CI provider proof contract',async()=>{
  const adapter=createCompanionCiProviderAdapter({execute:executor()});
  const proof=await proveCiProviderAdapter(adapter,{sourceSha:'a'.repeat(40)});
  assert.equal(proof.ok,true);
  assert.equal(proof.provider,'local-companion-ci');
  assert.equal(proof.dispatch,true);
  assert.equal(proof.artifact_read,true);
});

test('companion CI adapter fails closed when local device is offline',async()=>{
  const adapter=createCompanionCiProviderAdapter({
    execute:async()=>({ok:false,code:'DEVICE_OFFLINE'}),
  });
  const health=await adapter.health();
  assert.equal(health.ok,false);
  assert.equal(health.status,'UNAVAILABLE');
  assert.equal(health.code,'DEVICE_OFFLINE');
});


test('CI proof rejects a run that did not finish successfully',async()=>{
  const a=new CiProviderAdapter({
    id:'ci.alt',
    provider:'alternate-ci',
    health:async()=>({ok:true}),
    dispatch:async()=>({ok:true,run_id:'run-2'}),
    getRun:async()=>({ok:true,run_id:'run-2',source_sha:'a'.repeat(40),status:'FAILED'}),
    getArtifacts:async()=>({ok:true,artifacts:[]}),
    cancelRun:async()=>({ok:true}),
  });
  const result=await proveCiProviderAdapter(a,{sourceSha:'a'.repeat(40)});
  assert.equal(result.ok,false);
  assert.equal(result.status,'CI_PROVIDER_PROOF_RUN_NOT_SUCCESSFUL');
});

// MEL-FOUNDER-06: the Companion CI adapter is exercised without a Windows host.
test('the companion executor double announces itself and drives the adapter without hardware', async () => {
  const { createCompanionCiProviderAdapter, createCompanionExecutorDouble } = await import('../../src/portability/companion-ci-provider-adapter.js');
  const double = createCompanionExecutorDouble();
  assert.equal(double.kind, 'EXPLICIT_DOUBLE');
  assert.equal(double.hardware, false, 'nothing may read it as a real companion');

  const adapter = createCompanionCiProviderAdapter({ execute: double });
  const health = await adapter.health();
  assert.equal(health.ok, true);
  assert.equal(health.node_version, 'v20.0.0');
  assert.equal(double.calls[0].action, 'health');
  assert.equal(double.calls[0].repository, 'meliturgos-cloudflare');

  const down = createCompanionExecutorDouble({ healthy: false });
  const unavailable = await createCompanionCiProviderAdapter({ execute: down }).health();
  assert.equal(unavailable.ok, false);
  assert.equal(unavailable.status, 'UNAVAILABLE');
  assert.equal(unavailable.code, 'COMPANION_UNAVAILABLE');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { maybeHandleComputerApi } from '../src/devices/computer-companion-api.js';
import { miniBlePairCommand } from '../src/devices/mini-usb-provision.js';
import { sqliteD1 } from './helpers/sqlite-d1.mjs';

const ownerAuth = 'Basic ' + Buffer.from('adrien:test').toString('base64');
const request = (path, method = 'GET', body = null, authenticated = true) => new Request('https://mel.test' + path, {
  method,
  headers: { ...(authenticated ? { authorization: ownerAuth } : {}), ...(body ? { 'content-type': 'application/json' } : {}) },
  ...(body ? { body: JSON.stringify(body) } : {}),
});

test('BLE pair command relays the MINI passkey from USB into the phone over adb, without Wi-Fi', () => {
  const { command, timeout_ms } = miniBlePairCommand();
  assert.equal(timeout_ms, 120000);
  assert.ok(command.length <= 8192);
  assert.match(command, /MELBLE PASSKEY \(\\d\{6\}\)/);
  assert.match(command, /'cmd','bluetooth_manager','enable'/);
  assert.match(command, /'input','text',\$pk/);
  assert.match(command, /VID_303A&PID_1001/);
  assert.match(command, /\$sp\.DtrEnable=\$false;\$sp\.RtsEnable=\$false/, 'opening the port must not reset the MINI');
  assert.doesNotMatch(command, /netsh|wlan|dl\.google|Expand-Archive/);
});

test('mini.ble.pair is owner-only and queues the fixed command', async () => {
  const DB = sqliteD1();
  const env = { DB, MELITURGOS_USER: 'adrien', MELITURGOS_PASSWORD: 'test' };
  assert.equal((await maybeHandleComputerApi(request('/api/computer/v1/status'), env)).status, 200);
  await DB.prepare('INSERT INTO computer_devices(id,token_hash,name,platform,capabilities,allowed_apps,halted,created_at,last_seen_at,metadata) VALUES(?,?,?,?,?,?,?,?,?,?)')
    .bind('pc-1', 'h', 'PC', 'windows', JSON.stringify(['computer.use']), JSON.stringify([]), 0, Date.now(), Date.now(), JSON.stringify({ remote_access_enabled: true })).run();
  const call = (auth = true) => maybeHandleComputerApi(request('/api/computer/v1/pc-control', 'POST', { computer_id: 'pc-1', action: 'mini.ble.pair', payload: { command: 'Write-Host INJECTED' } }, auth), env);
  assert.equal((await call(false)).status, 401);
  assert.equal((await call()).status, 202);
  const step = JSON.parse((await DB.prepare('SELECT plan_json FROM computer_commands').first()).plan_json).steps[0];
  assert.equal(step.action, 'system.exec');
  assert.equal(step.payload.command, miniBlePairCommand().command);
});

test('firmware announces the Bluetooth passkey on USB for a MINI without a usable screen', async () => {
  const src = await readFile(new URL('../firmware/waveshare-terminal/main/mel_terminal.cpp', import.meta.url), 'utf8');
  const fn = src.slice(src.indexOf('static void usb_passkey_task'), src.indexOf('void mel_terminal_start_usb_passkey_relay'));
  assert.match(fn, /mel_link_v2_server_pairing_passkey\(&passkey\)/);
  assert.match(fn, /MELBLE PASSKEY %06lu/);
  // 0.6.16 rebooted in a loop with its own usb_serial_jtag driver: the console carries it.
  assert.doesNotMatch(src, /usb_serial_jtag_driver_install|driver\/usb_serial_jtag\.h/);
  assert.doesNotMatch(src, /MELPROV|save_string\("wifi_pass", (ssid|pass)->/);
  const main = await readFile(new URL('../firmware/waveshare-terminal/main/main.cpp', import.meta.url), 'utf8');
  assert.match(main, /mel_terminal_start_usb_passkey_relay\(\);/);
});

// MEL-FOUNDER-06: the software bench covers pairing, permissions, shutdown and
// disconnection with explicit doubles; the physical recipe stays separate.
test('the software bench covers the four protocol steps with an explicit double and never claims a hardware proof', async () => {
  const m = await import('../src/devices/mini-usb-provision.js');
  assert.deepEqual(m.MINI_PROTOCOL_STEPS, ['pair', 'permissions', 'shutdown', 'disconnect']);

  const double = m.createMiniProtocolDouble();
  const ok = await m.runMiniProtocolBench(double);
  assert.equal(ok.passed, true);
  assert.deepEqual(double.calls, ['pair', 'permissions', 'shutdown', 'disconnect']);
  assert.equal(ok.proves, 'PROTOCOL_ONLY');
  assert.equal(ok.hardware_validated, false, 'a bench never validates hardware');
  assert.equal(ok.physical_recipe.validated, false, 'the physical recipe stays separate and unvalidated');
  assert.equal(ok.physical_recipe.reason, 'PHYSICAL_DEVICE_PROOF_REQUIRED');

  const broken = await m.runMiniProtocolBench(m.createMiniProtocolDouble({ fails: ['shutdown'] }));
  assert.equal(broken.passed, false);
  assert.equal(broken.steps.find(s => s.step === 'shutdown').code, 'MINI_SHUTDOWN_FAILED');
  assert.equal(broken.steps.find(s => s.step === 'disconnect').ok, true, 'a failed step never stops the bench');

  // Anything that is not an announced double is refused: no silent fake device.
  await assert.rejects(m.runMiniProtocolBench({ run: async () => ({ ok: true }) }), e => e.code === 'MINI_BENCH_EXPLICIT_DOUBLE_REQUIRED');
  await assert.rejects(m.runMiniProtocolBench({ kind: 'EXPLICIT_DOUBLE', hardware: true, run: async () => ({ ok: true }) }), e => e.code === 'MINI_BENCH_EXPLICIT_DOUBLE_REQUIRED');
});
